<?php
require __DIR__ . '/includes/admin_bootstrap.php';
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT) ?: 0;
$row = ['title'=>'','icon_class'=>'bx bx-code','short_description'=>'','details_title'=>'','details_description'=>'','details_image'=>'','detail_items'=>'[]','sort_order'=>0,'is_active'=>1];
if ($id) { $stmt=$pdo->prepare('SELECT * FROM services WHERE id=?'); $stmt->execute([$id]); $row=$stmt->fetch() ?: $row; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $id=(int)($_POST['id'] ?? 0); $items=array_values(array_filter(array_map('trim', preg_split('/\r\n|\r|\n/', (string)($_POST['detail_items'] ?? '')))));
    $data=[trim((string)$_POST['title']),trim((string)$_POST['icon_class']),trim((string)$_POST['short_description']),trim((string)$_POST['details_title']),trim((string)$_POST['details_description']),trim((string)$_POST['details_image']),json_encode($items),max(0,(int)$_POST['sort_order']),isset($_POST['is_active'])?1:0];
    if ($id) { $stmt=$pdo->prepare('UPDATE services SET title=?,icon_class=?,short_description=?,details_title=?,details_description=?,details_image=?,detail_items=?,sort_order=?,is_active=? WHERE id=?'); $stmt->execute([...$data,$id]); flash('success','Service updated.'); } else { $stmt=$pdo->prepare('INSERT INTO services (title,icon_class,short_description,details_title,details_description,details_image,detail_items,sort_order,is_active) VALUES (?,?,?,?,?,?,?,?,?)'); $stmt->execute($data); flash('success','Service created.'); } admin_redirect('services.php');
}
$page_title = $id ? 'Edit Service' : 'Add Service'; require __DIR__ . '/includes/header.php'; $items=json_list($row['detail_items']);
?><section class="form-panel"><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$id ?>"><div class="form-grid"><label>Title<input name="title" value="<?= e($row['title']) ?>" required></label><label>Icon class<input name="icon_class" value="<?= e($row['icon_class']) ?>" placeholder="bx bx-code" required></label><label class="full">Short description<textarea name="short_description" required><?= e($row['short_description']) ?></textarea></label><label>Details title<input name="details_title" value="<?= e($row['details_title']) ?>"></label><label>Details image filename<input name="details_image" value="<?= e($row['details_image']) ?>"></label><label class="full">Details description<textarea name="details_description" rows="5"><?= e($row['details_description']) ?></textarea></label><label class="full">Read More list items <small>One item per line</small><textarea name="detail_items" rows="7"><?= e(implode("\n", $items)) ?></textarea></label><label>Sort order<input type="number" name="sort_order" value="<?= (int)$row['sort_order'] ?>"></label><label class="checkbox"><input type="checkbox" name="is_active" <?= $row['is_active'] ? 'checked' : '' ?>> Visible on website</label></div><div class="form-actions"><a class="btn secondary" href="services.php">Cancel</a><button class="btn" type="submit">Save service</button></div></form></section><?php require __DIR__ . '/includes/footer.php'; ?>
